mapper.select:
select 
  from sal_order_line l join sal_order o on o.order_id = l.order_id
 where l.line_id in #{id}

mapper.update:
update sal_order_line
   set shipped_qty = #{shipped}, status = #{status}, done_by_ship_yn = #{doneByShip},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where line_id = #{id}

update sal_order
   set status = 'OPEN', row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where order_id = #{id} and status = 'CLOSED'
